import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('official DSH client bundle contributes one AR main panel and sidebar entry', async () => {
  const source = await readFile(new URL('../src/dsh/client.js', import.meta.url), 'utf8');
  assert.match(source, /window\.\__ModuleLoader__\.load/);
  assert.match(source, /ctx\.slots\.inject\('main'/);
  assert.match(source, /ctx\.slots\.inject\('sidebar\.panellist'/);
  assert.match(source, /\/api\/ohos-ar/);
  assert.match(source, /subagent_claude_code/);
  assert.match(source, /CodeAgent 设置/);
  assert.match(source, /模型（可选，适用于当前 CodeAgent）/);
  assert.match(source, /model: model\.trim\(\) \|\| null/);
  assert.match(source, /OpenCode/);
  assert.match(source, /\/codeagents/);
  assert.match(source, /\/rag\/search/);
  assert.match(source, /\/rag\/index/);
  assert.match(source, /\/rag\/profile/);
  assert.match(source, /embedding_reranker/);
  assert.match(source, /artifacts\/content/);
  assert.match(source, /artifacts\/download/);
  assert.match(source, /二进制产物已保留在 SSH 代码端/);
  assert.match(source, /下载原始文件/);
  assert.match(source, /scheduler/);
  assert.match(source, /execution_failures/);
  assert.match(source, /gate_pass_count/);
  assert.match(source, /stage_completion_count/);
  assert.match(source, /run_success_rate/);
  assert.match(source, /human_wait_open_count/);
  assert.match(source, /human_wait_intervals/);
  assert.match(source, /人工等待时长/);
  assert.match(source, /有效执行时长/);
  assert.match(source, /effective_elapsed_ms/);
  assert.match(source, /failure_reasons/);
  assert.match(source, /SCHEDULER_FAILURE/);
  assert.match(source, /export\?format=/);
  assert.match(source, /downloadExport\('json'\)/);
  assert.match(source, /downloadExport\('csv'\)/);
  assert.match(source, /导出 JSON/);
  assert.match(source, /导出 CSV/);
  assert.match(source, /setInterval\(\(\) => loadDetail\(selected\), 3500\)/);
  assert.match(source, /function formatTokenUsage/);
  assert.match(source, /formatTokenUsage\(observation\.token_usage\)/);
  assert.match(source, /device_serial/);
  assert.match(source, /pipeline_dir/);
  assert.match(source, /environment === 'harmonyos'/);
  assert.match(source, /needsDefaultConfirmation/);
  assert.match(source, /workspace_mode/);
  assert.match(source, /前置条件检查/);
  assert.match(source, /\/preflight/);
  assert.match(source, /local_cli_remote_edit/);
  assert.match(source, /agent_load_strategy/);
  assert.match(source, /agent_profile_id/);
  assert.match(source, /agent_auth_source/);
  assert.match(source, /预检环境/);
  assert.match(source, /component_type=/);
  assert.match(source, /device_type=/);
  assert.match(source, /device_serial=/);
  assert.match(source, /repo_root/);
  assert.match(source, /SSH 项目目录/);
  assert.match(source, /agent=/);
  assert.match(source, /model=/);
  assert.match(source, /function environmentSummary/);
  assert.match(source, /环境 \$\{environmentLabel\}/);
  assert.match(source, /分支 \$\{component\}/);
  assert.match(source, /设备 \$\{device\}/);
  assert.match(source, /ready_for_p0/);
  assert.match(source, /preflightBeforeStart/);
  assert.match(source, /process_supervisor/);
  assert.match(source, /受监督进程/);
  assert.match(source, /CodeAgent 进程监督/);
  assert.match(source, /\/processes\?run_id=/);
  assert.doesNotMatch(source, /127\.0\.0\.1:8788/);
});

test('official profile disables API-key onboarding and exposes Claude Code through the default preset', async () => {
  const patch = await readFile(new URL('../cordis.patch.yml', import.meta.url), 'utf8');
  const preset = await readFile(new URL('../config/presets/claude-code/agent.cordis.yml', import.meta.url), 'utf8');
  assert.match(patch, /id: ui-settings-models[\s\S]*disabled: true/);
  assert.match(patch, /name: '@deepseek-ai\/dsh-subagent-claude-code'/);
  assert.match(patch, /default: 'claude-code'/);
  const claudeRow = preset.slice(preset.indexOf('- id: tool-subagent-claude-code'), preset.indexOf('- id: workflow-worker-thread'));
  assert.match(claudeRow, /toolName: subagent_claude_code/);
  assert.doesNotMatch(claudeRow, /disabled:/);
});
